def list_workspaces(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0153000" if __import__("os").path.isdir("./environment_mix/0153000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid 'status' filter value.", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Field 'limit' must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Field 'limit' must be between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Field 'cursor' must be a string.", field="cursor")

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    workspaces_obj = _load("workspaces.json")
    api_keys_obj = _load("api_keys.json")
    workspaces = _rows(workspaces_obj)
    api_keys = _rows(api_keys_obj)

    # Resolve visibility: any workspace with at least one active api key is "visible"
    visible_ws_ids = {k.get("workspace_id") for k in api_keys if k.get("status") == "active" and k.get("workspace_id")}
    if not visible_ws_ids:
        return _err("UNAUTHORIZED", "No active API key context available.")

    # Cursor: accept either raw workspace id (as used by audit) OR base64-encoded json {"after_id": "..."}
    after_id = None
    if cursor:
        # Try raw id first
        if any(w.get("id") == cursor for w in workspaces):
            after_id = cursor
        else:
            # Try base64 json
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                obj = json.loads(raw.decode("utf-8"))
                after_id = obj.get("after_id")
            except Exception:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            if after_id is not None and not isinstance(after_id, str):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    rows = [w for w in workspaces if w.get("id") in visible_ws_ids]
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]

    # Sort by id asc (stable)
    rows.sort(key=lambda r: (r.get("id") or ""))

    if after_id:
        # start after the cursor id (even if it's not visible anymore, behave gracefully)
        idx = -1
        for i, w in enumerate(rows):
            if w.get("id") == after_id:
                idx = i
                break
        if idx >= 0:
            rows = rows[idx + 1 :]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        next_cursor = page[-1].get("id")

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "workspaces": page,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "latency_ms": latency_ms,
    }

def get_workspace(workspace_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0153000" if __import__("os").path.isdir("./environment_mix/0153000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(workspace_id, str) or workspace_id.strip() == "":
        return _err("VALIDATION_ERROR", "Field 'workspace_id' must be a non-empty string.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    executions = _load("query_executions.json")
    datasources = _load("datasources.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")

    visible_ws_ids = {k.get("workspace_id") for k in api_keys if k.get("status") == "active" and k.get("workspace_id")}
    if workspace_id not in visible_ws_ids:
        return _err("UNAUTHORIZED", "Workspace not visible to caller.")

    # log dynamics if possible
    api_key = next((k for k in api_keys if k.get("status") == "active" and k.get("workspace_id") == workspace_id), None) \
              or next((k for k in api_keys if k.get("status") == "active" and k.get("workspace_id")), None)
    ds_id = None
    if api_key:
        ws_for_log = api_key.get("workspace_id")
        ws_row = next((w for w in workspaces if w.get("id") == ws_for_log), None)
        if ws_row:
            cand = ws_row.get("default_datasource_id")
            if cand and any(d.get("id") == cand and d.get("workspace_id") == ws_for_log for d in datasources):
                ds_id = cand
        if ds_id:
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            req = {
                "id": f"qe_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(8).hex()}",
                "workspace_id": ws_for_log,
                "api_key_id": api_key.get("id"),
                "datasource_id": ds_id,
                "request_query": "/* get_workspace */",
                "normalized_query": None,
                "query_fingerprint": None,
                "status": "succeeded",
                "started_at": None,
                "finished_at": now,
                "duration_ms": int((time.time() - t0) * 1000),
                "rows_affected": None,
                "result_row_count": 1,
                "result_truncated": False,
                "result_preview_json": None,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now,
            }
            executions.append(req)
            _save("query_executions.json", executions)

    return {"workspace": ws}

def update_workspace(workspace_id, name=None, default_datasource_id=None, status=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0153000" if __import__("os").path.isdir("./environment_mix/0153000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- validation
    if not isinstance(workspace_id, str) or workspace_id.strip() == "":
        return _err("VALIDATION_ERROR", "Field 'workspace_id' must be a non-empty string.", field="workspace_id")
    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "Field 'name' must be a string.", field="name")
        if not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "Field 'name' must be between 1 and 200 characters.", field="name")
    if default_datasource_id is not None:
        if not isinstance(default_datasource_id, str) or default_datasource_id.strip() == "":
            return _err("VALIDATION_ERROR", "Field 'default_datasource_id' must be a non-empty string.", field="default_datasource_id")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid 'status' value.", field="status")

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _persist(filename, obj, rows_list):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            obj["rows"] = rows_list
            _save(filename, obj)
        else:
            _save(filename, rows_list)

    workspaces_obj = _load("workspaces.json")
    datasources_obj = _load("datasources.json")

    workspaces = _rows(workspaces_obj)
    datasources = _rows(datasources_obj)

    ws_idx = None
    ws = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws_idx = i
            ws = w
            break
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # ---- enforce unique(name) only when changing and conflict is with another workspace
    if name is not None:
        for other in workspaces:
            if not isinstance(other, dict):
                continue
            if other.get("id") == workspace_id:
                continue
            if other.get("name") == name:
                return _err(
                    "CONFLICT",
                    "Workspace name must be unique (constraint: unique(name)).",
                    field="name",
                    name=name
                )

    # ---- validate default_datasource_id ownership + active, and reference must exist
    if default_datasource_id is not None:
        ds = None
        for d in datasources:
            if isinstance(d, dict) and d.get("id") == default_datasource_id:
                ds = d
                break
        if ds is None:
            return _err("NOT_FOUND", "Datasource not found.", default_datasource_id=default_datasource_id)
        if ds.get("workspace_id") != workspace_id:
            return _err(
                "VALIDATION_ERROR",
                "default_datasource_id must reference a datasource in the same workspace (constraint: default_datasource_id references datasources.id and must belong to same workspace).",
                field="default_datasource_id",
                default_datasource_id=default_datasource_id
            )
        if ds.get("status") != "active":
            return _err(
                "INVALID_TRANSITION",
                "Default datasource must be active to set as workspace default.",
                field="default_datasource_id",
                default_datasource_id=default_datasource_id,
                datasource_status=ds.get("status")
            )

    # ---- lifecycle transition for status
    if status is not None:
        current = ws.get("status")
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": []
        }
        if current not in transitions:
            return _err("INVALID_TRANSITION", "Workspace has an unknown lifecycle state.", status=current)
        if status != current:
            if status not in transitions[current]:
                return _err(
                    "INVALID_TRANSITION",
                    "Illegal workspace status transition.",
                    from_status=current,
                    to_status=status
                )

    # ---- apply changes (must have effect)
    changed = False
    if name is not None and name != ws.get("name"):
        ws["name"] = name
        changed = True
    if default_datasource_id is not None and default_datasource_id != ws.get("default_datasource_id"):
        ws["default_datasource_id"] = default_datasource_id
        changed = True
    if status is not None and status != ws.get("status"):
        ws["status"] = status
        changed = True

    if not changed:
        # No mutation effect is still a valid update in many APIs, but contract demands no success without effect.
        # Here, report NOT_FOUND-equivalent for mutation with no changes.
        return _err("CONFLICT", "Update request made no changes to the workspace.", workspace_id=workspace_id)

    ws["updated_at"] = now
    workspaces[ws_idx] = ws
    _persist("workspaces.json", workspaces_obj, workspaces)

    return {"workspace": ws}

def create_api_key(workspace_id, name, **_extra):
    import json, os, datetime, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0153000" if __import__("os").path.isdir("./environment_mix/0153000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string")
    if not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "name length must be between 1 and 200")

    # Load store
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    # Resolve workspace (ambient auth: choose a workspace that can satisfy prerequisites)
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") != "active":
        return _err("INVALID_TRANSITION", "Workspace is not active", workspace_id=workspace_id, status=ws.get("status"))

    # Enforce unique(workspace_id, name)
    for k in api_keys:
        if k.get("workspace_id") == workspace_id and k.get("name") == name:
            return _err("CONFLICT", "API key name already exists in this workspace", workspace_id=workspace_id, name=name)

    # Generate a secret once; store only hash + prefix
    raw_token = "sk_" + secrets.token_urlsafe(32)
    key_prefix = raw_token[:8]

    # Enforce unique(key_prefix, workspace_id)
    for k in api_keys:
        if k.get("workspace_id") == workspace_id and k.get("key_prefix") == key_prefix:
            # Retry a few times to avoid collision
            collided = True
            for _ in range(10):
                raw_token = "sk_" + secrets.token_urlsafe(32)
                key_prefix = raw_token[:8]
                if not any(kk.get("workspace_id") == workspace_id and kk.get("key_prefix") == key_prefix for kk in api_keys):
                    collided = False
                    break
            if collided:
                return _err("CONFLICT", "Failed to generate a unique key prefix; please retry")

    # Hash (no plaintext storage); ensure unique(key_hash)
    key_hash = hashlib.sha256(raw_token.encode("utf-8")).hexdigest()
    if any(k.get("key_hash") == key_hash for k in api_keys):
        # Extremely unlikely; treat as conflict and retry behavior not required by tool
        return _err("CONFLICT", "Failed to generate a unique key hash; please retry")

    # Generate id with a stable prefix
    existing_ids = {k.get("id") for k in api_keys if isinstance(k.get("id"), str)}
    new_id = None
    for _ in range(50):
        cand = "key_" + secrets.token_hex(12)
        if cand not in existing_ids:
            new_id = cand
            break
    if not new_id:
        return _err("CONFLICT", "Failed to allocate a new api_key id; please retry")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": name,
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)

    # Return token once + metadata (token not stored)
    return {
        "api_key": {
            "id": row["id"],
            "workspace_id": row["workspace_id"],
            "name": row["name"],
            "key_prefix": row["key_prefix"],
            "status": row["status"],
            "last_used_at": row["last_used_at"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
        "key": raw_token,
        "meta": {"latency_ms": latency_ms},
    }

def update_api_key(api_key_id, name=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0153000" if __import__("os").path.isdir("./environment_mix/0153000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    # Validate inputs
    if not isinstance(api_key_id, str) or not api_key_id.strip():
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")
    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string")
        if not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "name length must be between 1 and 200")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked")

    api_keys = _load("api_keys.json")

    # Find key
    idx = None
    row = None
    for i, k in enumerate(api_keys):
        if k.get("id") == api_key_id:
            idx = i
            row = k
            break
    if row is None:
        return _err("NOT_FOUND", "API key not found", api_key_id=api_key_id)

    # Apply updates with constraints
    # unique(workspace_id, name)
    if name is not None and name != row.get("name"):
        wsid = row.get("workspace_id")
        for k in api_keys:
            if k.get("id") != api_key_id and k.get("workspace_id") == wsid and k.get("name") == name:
                return _err("CONFLICT", "API key name already exists in this workspace", workspace_id=wsid, name=name)

    # Lifecycle transitions for status: active -> revoked only
    if status is not None and status != row.get("status"):
        cur = row.get("status")
        if cur == "active" and status == "revoked":
            row["status"] = "revoked"
        elif cur == "revoked" and status == "active":
            return _err("INVALID_TRANSITION", "Cannot un-revoke a revoked key", api_key_id=api_key_id)
        else:
            return _err("INVALID_TRANSITION", "Illegal status transition", api_key_id=api_key_id, from_status=cur, to_status=status)

    if name is not None:
        row["name"] = name

    # If nothing changed, still return current metadata (idempotent update)
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row["updated_at"] = now
    api_keys[idx] = row
    _save("api_keys.json", api_keys)

    latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)

    return {
        "api_key": {
            "id": row.get("id"),
            "workspace_id": row.get("workspace_id"),
            "name": row.get("name"),
            "key_prefix": row.get("key_prefix"),
            "status": row.get("status"),
            "last_used_at": row.get("last_used_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }
